/* type the modem's bytes as they come, until 2 s pass with none;
   returns how many came in all */
static uint16_t type_raw(void)
{
    uint16_t n, total = 0;

    while ((n = raw_get(mbuf, sizeof mbuf - 1)) != 0) {
        mbuf[n] = 0;
        printf("%s", (char *)mbuf);
        total += n;
    }
    return total;
}

