/* Ask every 0.5 s, for up to 15 s, until a caller waits
   ("connected" = 1): 1 if one does, 0 if no one came. */
static uint8_t wait_caller(const char *spec)
{
    uint8_t n, i;

    for (n = 0; n < 30; n++) {
        network_status(spec, &avail, &conn, &nerr);
        if (conn)
            break;
        for (i = 0; i < 5; i++)
            pause_tenth();
    }
    return conn;
}
